/* aesthetic rows v2.18.1 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-w-medium: 550;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
}

.ae-row-link {
display: block;
  text-decoration: none;
  padding: 0.42em 0;
  margin-block: 0;
  color: inherit;
}

.ae-row-link:hover {
color: inherit;
}

.ae-row-link .ae-item {
transition: color var(--ae-quick) var(--ae-ease);
}

.ae-row-link:hover .ae-item {
color: var(--ae-accent);
}

.ae-item {
font-weight: var(--ae-w-medium);
}

.ae-dim {
color: var(--ae-ink-muted);
}
